package com.ruoyi.metal.service;
import java.util.*;import java.io.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.math.BigDecimal;import org.springframework.stereotype.Service;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.*;import org.apache.poi.xssf.streaming.SXSSFWorkbook;import org.apache.poi.ss.usermodel.*;import com.ruoyi.metal.catalog.*;import org.slf4j.LoggerFactory;
@Service public class BusinessExportService {
 private final JdbcTemplate jdbc;private final BusinessQueries queries;private final WarehouseService warehouse;
 @org.springframework.beans.factory.annotation.Autowired public BusinessExportService(JdbcTemplate jdbc,BusinessQueries queries,WarehouseService warehouse){this.jdbc=jdbc;this.queries=queries;this.warehouse=warehouse;}
 public BusinessExportService(JdbcTemplate jdbc,BusinessQueries queries){this(jdbc,queries,null);}
 private record Column(String key,String label){}
 private static class Writer {final SXSSFWorkbook book;final String title;final Column[] columns;int number=0,row;Sheet sheet;final CellStyle heading;Writer(SXSSFWorkbook b,String title,Column...c){book=b;this.title=title;columns=c;heading=b.createCellStyle();var font=b.createFont();font.setBold(true);heading.setFont(font);next();}void next(){sheet=book.createSheet(title+(number++==0?"":"-"+number));row=0;var head=sheet.createRow(row++);for(int i=0;i<columns.length;i++){head.createCell(i).setCellValue(columns[i].label);head.getCell(i).setCellStyle(heading);sheet.setColumnWidth(i,(columns[i].key.equals("specification")?45:24)*256);}sheet.createFreezePane(0,1);}void add(Map<String,Object> data){if(row>=1048576)next();var r=sheet.createRow(row++);for(int i=0;i<columns.length;i++){Object value=data.get(columns[i].key);String text=value==null?"":value instanceof BigDecimal d?BusinessDecimal.display(d):value instanceof java.sql.Timestamp t?t.toLocalDateTime().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")):value.toString();r.createCell(i).setCellValue(text);}}}
 private static Column c(String key,String label){return new Column(key,label);}
 @Transactional(isolation=Isolation.REPEATABLE_READ,rollbackFor=Exception.class)
 public long inventory(InventoryListQuery query,OutputStream output)throws IOException{
  queries.inventory(query);if(query.getFilter()==null)throw new com.ruoyi.common.exception.ServiceException("请先选择库存分类再导出");
  var book=new SXSSFWorkbook(100);try(book){book.setCompressTempFiles(true);Column[] columns=switch(query.getFilter()){
   case "RAW"->new Column[]{c("code","物料编码"),c("materialType","物料类型"),c("specification","规格型号"),c("customerCompanyName","客户公司名称"),c("netWeight","净重（g）")};
   case "SEMI"->new Column[]{c("customerName","客户名称"),c("name","产品名称"),c("productType","产品类型"),c("metalTypeName","金属类型"),c("sourceProcessName","来源工序"),c("netWeight","净重（g）"),c("quantityDisplay","数量 / 参考")};
   default->new Column[]{c("name","产品名称"),c("productType","产品类型"),c("metalTypeName","金属类型"),c("specification","规格型号"),c("quantityDisplay","数量"),c("customerCompanyName","客户公司名称")};};
   var writer=new Writer(book,"库存",columns);long count=0;for(long offset=0;;offset+=1000){var rows=warehouse.inventoryRows(query,1000,offset);for(var row:rows){row.put("quantityDisplay","WEIGHT".equals(row.get("measurementMode"))?"参考："+(Boolean.FALSE.equals(row.get("referenceComplete"))?"未完整记录":Objects.toString(row.get("referenceQuantity"),"未记录")):row.get("quantity"));if(row.get("customerCompanyName")==null)row.put("customerCompanyName",row.get("customerId")==null?"未关联客户":"历史未记录");writer.add(row);}count+=rows.size();if(rows.size()<1000)break;}book.write(output);return count;
  }finally{book.dispose();}
 }
 @Transactional(isolation=Isolation.REPEATABLE_READ,rollbackFor=Exception.class)
 public long staff(ListQuery q,OutputStream output)throws IOException{
  var p=queries.staff(q);var book=new SXSSFWorkbook(100);try(book){book.setCompressTempFiles(true);var writer=new Writer(book,"人员",c("user_name","登录账号"),c("phonenumber","手机号"),c("nick_name","姓名"),c("factory_name","所属工厂"),c("roles","角色"),c("status_name","状态"),c("create_time","创建时间"));long count=0;for(int offset=0;;offset+=1000){var args=new ArrayList<>(p.args());args.add(offset);var rows=jdbc.queryForList("SELECT u.user_name,u.phonenumber,u.nick_name,f.factory_name,(SELECT GROUP_CONCAT(r.role_name ORDER BY r.role_sort,r.role_id SEPARATOR '、') FROM sys_user_role ur JOIN sys_role r ON r.role_id=ur.role_id WHERE ur.user_id=u.user_id) roles,CASE u.status WHEN '0' THEN '启用' ELSE '停用' END status_name,u.create_time FROM sys_user u LEFT JOIN metal_factory f ON f.factory_id=u.factory_id WHERE "+p.sql()+" ORDER BY u.user_id DESC LIMIT 1000 OFFSET ?",args.toArray());for(var row:rows)writer.add(row);count+=rows.size();if(rows.size()<1000)break;}book.write(output);LoggerFactory.getLogger(getClass()).info("BUSINESS_EXPORT kind=staff count={} factory={}",count,q.getFactoryId());return count;}finally{book.dispose();}
 }
 private static final Map<String,String> TYPES=Map.ofEntries(Map.entry("OWNERSHIP_OUT","抵料客户归属转出"),Map.entry("OWNERSHIP_IN","抵料厂料归属转入"),Map.entry("RESIDUAL_STORAGE","客户余料代存确认"),Map.entry("ACID_OUT","酸洗领料"),Map.entry("ACID_IN","酸洗金属料入库"),Map.entry("ACID_RETURN","酸洗余料还库"),Map.entry("PRODUCTION_OUT","生产出库"),Map.entry("PRODUCT_OUT","产品出库"),Map.entry("EXCHANGE_OUT","还料出库"),Map.entry("SEMI_OUT","半成品出库"),Map.entry("RAW_IN","原材料入库"),Map.entry("RAW_PROCESS_IN","原料加工产出入库"),Map.entry("FINISHED_IN","成品入库"),Map.entry("SEMI_IN","半成品入库"),Map.entry("PROCESS_RAW_RETURN","加工余料还库"),Map.entry("RAW_RETURN","原料还库"),Map.entry("SEMI_RETURN","半成品还库"),Map.entry("PRODUCT_RETURN","成品退还"),Map.entry("OPENING","期初登记"),Map.entry("ADJUST","库存调整"));
 @Transactional(isolation=Isolation.REPEATABLE_READ,rollbackFor=Exception.class)
 public long orders(OrderListQuery q,OutputStream output)throws IOException{
  var p=queries.orders(q);var book=new SXSSFWorkbook(100);try(book){book.setCompressTempFiles(true);var summary=new Writer(book,"单据汇总",c("order_no","单据编号"),c("work_order_no","生产工单号"),c("factory_name","工厂"),c("order_date","单据日期"),c("warehouse_name","仓库"),c("type_name","类型"),c("operator_name","经办人"),c("recipient_name","领用人"),c("inspector_name","验收人"),c("keeper_name","仓管人"),c("reviewer_name","审核人"),c("status_name","状态"));Column[] detailColumns={c("order_no","单据编号"),c("sequence_no","行序号"),c("code","物料编码"),c("name","品名"),c("category_name","类别"),c("specification","规格型号"),c("batch_no","批次号"),c("gross_weight","毛重(g)"),c("impurity","杂质(g)"),c("net_weight","净重(g)"),c("quantity","数量"),c("measurement_mode_name","计量方式"),c("reference_quantity","参考件数（选填）"),c("purity","纯度(%)"),c("organization","单位名称"),c("receiving_organization","收货单位"),c("purpose","用途"),c("remark","备注"),c("release_id","半成品释放记录ID"),c("source_work_order_no","来源工单"),c("source_process_name","已完成来源工序"),c("source_order_no","原出库单")};boolean rawOnly=Set.of("RAW_IN","RAW_PROCESS_IN","RAW_RETURN","PROCESS_RAW_RETURN","EXCHANGE_OUT","ACID_IN","ACID_OUT","ACID_RETURN").contains(Objects.toString(q.getType(),""));var lines=new Writer(book,"物料明细",Arrays.stream(detailColumns).filter(c->!rawOnly||!Set.of("quantity","reference_quantity").contains(c.key())).toArray(Column[]::new));long count=0,detailCount=0;
  for(int offset=0;;offset+=1000){var args=new ArrayList<>(p.args());args.add(offset);var rows=jdbc.queryForList("SELECT t.order_id,t.order_no,t.order_date,t.warehouse_name,t.type,t.operator_name,t.recipient_name,t.inspector_name,t.keeper_name,t.reviewer_name,t.status,f.factory_name,w.order_no work_order_no FROM metal_warehouse_order t LEFT JOIN metal_factory f ON f.factory_id=t.factory_id LEFT JOIN metal_work_order w ON w.work_order_id=t.work_order_id WHERE "+p.sql()+" ORDER BY t.order_id LIMIT 1000 OFFSET ?",args.toArray());for(var row:rows){row.put("type_name",TYPES.getOrDefault(Objects.toString(row.get("type")),""));row.put("status_name",switch(Objects.toString(row.get("status"))){case "POSTED"->"已生效";case "VOID"->"已冲销";case "WAITING_OUT"->"待实领";case "WAITING_IN"->"待库管验收";case "RETURNED"->"已退回修订";case "CANCELLED"->"已取消";default->"待核对";});summary.add(row);}if(!rows.isEmpty()){var ids=rows.stream().map(r->r.get("order_id")).toArray();String placeholders=String.join(",",Collections.nCopies(ids.length,"?"));jdbc.query("SELECT l.*,t.order_no,u.release_id,sw.order_no source_work_order_no,ss.process_name source_process_name,so.order_no source_order_no FROM metal_warehouse_order_line l JOIN metal_warehouse_order t ON t.order_id=l.order_id LEFT JOIN metal_semi_release_use u ON u.line_id=COALESCE(l.source_line_id,l.line_id) LEFT JOIN metal_inventory si ON si.inventory_id=l.inventory_id LEFT JOIN metal_process_batch sb ON sb.batch_id=si.origin_batch_id LEFT JOIN metal_work_order sw ON sw.work_order_id=sb.work_order_id LEFT JOIN metal_work_order_step ss ON ss.item_id=sb.item_id AND ss.process_id=sb.process_id LEFT JOIN metal_warehouse_order_line sl ON sl.line_id=l.source_line_id LEFT JOIN metal_warehouse_order so ON so.order_id=sl.order_id WHERE l.order_id IN ("+placeholders+") ORDER BY l.order_id,l.sequence_no",(org.springframework.jdbc.core.RowCallbackHandler)rs->{Map<String,Object> row=new HashMap<>();var metadata=rs.getMetaData();for(int i=1;i<=metadata.getColumnCount();i++)row.put(metadata.getColumnLabel(i),rs.getObject(i));row.put("category_name",switch(Objects.toString(row.get("category"))){case "RAW"->"原材料";case "SEMI"->"半成品";default->"成品";});if("WEIGHT".equals(row.get("measurement_mode"))||"RAW".equals(row.get("category"))){row.put("quantity",null);row.put("measurement_mode_name","按重量");}else row.put("measurement_mode_name","按件");lines.add(row);},ids);}count+=rows.size();if(rows.size()<1000)break;}
  book.write(output);LoggerFactory.getLogger(getClass()).info("BUSINESS_EXPORT kind=warehouse-order count={} factory={}",count,q.getFactoryId());return count;}finally{book.dispose();}
 }
}
